require "rails_helper"

RSpec.describe Invoices::ReservationRequest do
  # "The intent must store the whole request, so retries and recovery resend the stored bytes and never recompute."
  # A request the caller can still change would resend different entries on retry.
  it "keeps the stored entries when the caller changes its array after building the request" do
    entries = [3, 1, 3]
    request = described_class.new(company_id: 1, invoice_id: 10, operation_id: SecureRandom.uuid,
                                  generation: 1, disposition: "active", entries:)

    entries << 99
    entries.delete(1)

    expect(request.entries).to eq([1, 3])
    expect(request.entries).to be_frozen
    expect(entries).not_to be_frozen
  end
end

require "rails_helper"

RSpec.describe Invoices::ReservationRequest do
  # The request is the only carrier of the company scope across the reservation port,
  # and disposition is "active" or "retained" only.
  it "refuses a request with no company or an unknown disposition" do
    base = { company_id: 1, invoice_id: 10, operation_id: SecureRandom.uuid, generation: 1,
             disposition: "active", entries: [1] }

    expect { described_class.new(**base, company_id: nil) }.to raise_error(ArgumentError)
    expect { described_class.new(**base, disposition: "deleted") }.to raise_error(ArgumentError)
  end
end
